//! Parses `calibration.json` -- the design: "per-type, per-language
//! thresholds ... regenerated by `pii-detection-eval`." This is the artifact's
//! *only* parser, deliberately: `pii-detection-model::artifact::Artifact::load`
//! digest-verifies and UTF-8 decodes the file but leaves it as a raw string
//! on purpose, so the threshold schema is defined in exactly one place.
//!
//! WHY LOOKUP FAILS CLOSED, THE SAME WAY `thresholds.toml`'S DOES.
//! [`Calibration::threshold`] returns `None` for a type this file never
//! mentions, in either its `default` block or under the requested language.
//! `pii-detection-resolve`'s existing rule for `thresholds.toml` -- an uncalibrated
//! type gets `f32::INFINITY`, so it never matches until it is calibrated --
//! is deliberately mirrored here rather than replaced with a guessed
//! fallback: an unreviewed type must never end up with a *more* permissive
//! bar than every type someone actually calibrated.
//!
//! WHY `auto` AND EVERY UNSUPPORTED LANGUAGE FALL BACK TO `default`. There is
//! no `pii-detection-lang` crate, so a request's `language` is never resolved to one
//! of the six languages the model supports before it reaches the resolver.
//! `default` is generated over the pool of all six supported languages
//! together (`en`, `nl`, `de`, `fr`, `es`, `it` -- see
//! `crates/eval/src/bin/calibrate.rs`), so it is a sound fallback for
//! `"auto"` and for every language `calibrate` never saw at all: both get the
//! threshold that held across the whole supported pool, not a guess.
//!
//! WHY A THRESHOLD OUTSIDE `0.0..=1.0` IS REJECTED AT PARSE TIME, RATHER THAN
//! LEFT TO SILENTLY MISBEHAVE. A generator bug that emitted a raw logit
//! instead of a sigmoid-ed probability would otherwise either disable a type
//! outright (a threshold above every real score) or accept everything (a
//! threshold below every real score) -- and either failure reads, downstream,
//! as a detection regression rather than what it actually is: a malformed
//! artifact. `from_json` refuses to load rather than let that reach
//! production.
//!
//! WHY AN UNKNOWN TYPE NAME FAILS THE WHOLE FILE. `EntityType::from_wire`
//! already refuses a name the detector's taxonomy has never heard of (see
//! `pii_detection_engine::entity`'s own tests) for exactly this reason: a type that
//! can never match would sit in its own denominator as a permanent, silent
//! miss. A `calibration.json` naming one is symptomatic of the same
//! generator bug the range check exists for, and is refused the same way.

use std::collections::BTreeMap;

use pii_detection_engine::entity::EntityType;
use serde::Deserialize;

/// A threshold must be a probability, never a raw score of any other scale.
const VALID_THRESHOLD_RANGE: std::ops::RangeInclusive<f32> = 0.0..=1.0;

/// Every way `calibration.json` can fail to load.
///
/// No variant carries a byte of the file's own content beyond a type's own
/// wire name (`"PERSON"`, never text drawn from a request or a detected
/// value) or a JSON parse position -- the design's discipline against
/// a text-bearing exception message, held the same way
/// `pii_detection_model::artifact::ArtifactError` holds it for the rest of the
/// artifact.
#[derive(Debug, thiserror::Error, PartialEq, Eq)]
pub enum CalibrationError {
    #[error("calibration.json is not valid JSON (line {line}, column {column})")]
    Malformed { line: usize, column: usize },
    /// A `default` or `languages` block names a type outside Temperate's
    /// taxonomy (`EntityType::from_wire` returned `None`).
    #[error("calibration.json names an entity type Temperate does not have: {wire}")]
    UnknownEntityType { wire: String },
    /// A threshold fell outside `0.0..=1.0` -- see the module docs.
    #[error("calibration.json's threshold for {wire} is outside 0.0..=1.0")]
    ThresholdOutOfRange { wire: String },
}

/// The shape `calibration.json` actually has on disk, deserialized with
/// string keys before [`EntityType`] validation runs -- so an unknown type
/// name produces [`CalibrationError::UnknownEntityType`] instead of a bare
/// serde error with no say in the message.
#[derive(Deserialize)]
struct RawCalibration {
    revision: String,
    #[serde(default)]
    default: BTreeMap<String, f32>,
    #[serde(default)]
    languages: BTreeMap<String, BTreeMap<String, f32>>,
    // `notes` (the sample-floor omissions `calibrate` records) and
    // `generated_by` are present on a real artifact and read by nobody here
    // -- serde ignores unknown fields by default, so this struct simply
    // never names them, rather than parsing and immediately discarding them.
}

/// Per-type, per-language detection thresholds for model-sourced candidates
/// -- the design. Rule-sourced candidates never consult this; they
/// keep using `crate::thresholds` (`thresholds.toml`), untouched by whatever
/// this file says. See `Resolver::resolve`'s doc comment for where the split
/// happens.
#[derive(Debug, Clone, PartialEq)]
pub struct Calibration {
    revision: String,
    default: BTreeMap<EntityType, f32>,
    languages: BTreeMap<String, BTreeMap<EntityType, f32>>,
}

impl Calibration {
    /// Parses and validates a `calibration.json` document. Every type name
    /// in `default` and in every language block must be one
    /// `EntityType::from_wire` recognises, and every threshold must lie in
    /// `0.0..=1.0` -- see the module docs for why both are hard failures
    /// rather than warnings.
    pub fn from_json(raw: &str) -> Result<Calibration, CalibrationError> {
        let parsed: RawCalibration =
            serde_json::from_str(raw).map_err(|error| CalibrationError::Malformed {
                line: error.line(),
                column: error.column(),
            })?;

        let default = validate_thresholds(parsed.default)?;
        let mut languages = BTreeMap::new();
        for (language, raw_thresholds) in parsed.languages {
            languages.insert(language, validate_thresholds(raw_thresholds)?);
        }

        Ok(Calibration {
            revision: parsed.revision,
            default,
            languages,
        })
    }

    /// The threshold a model-sourced candidate of `entity_type` needs to
    /// clear when the request's language is `language`.
    ///
    /// Language-specific first, `default` second, `None` when neither block
    /// mentions the type at all -- see the module docs on why `None` (fail
    /// closed) is the only safe answer for a type nobody calibrated, and why
    /// `"auto"` and every language `calibrate` never saw fall straight
    /// through to `default`: there is no lookup keyed by anything else for
    /// them to hit first.
    pub fn threshold(&self, entity_type: EntityType, language: &str) -> Option<f32> {
        self.languages
            .get(language)
            .and_then(|thresholds| thresholds.get(&entity_type))
            .or_else(|| self.default.get(&entity_type))
            .copied()
    }

    /// What `GET /health` reports in its `calibration` field: an opaque
    /// label identifying which fit is loaded, never interpreted here.
    pub fn revision(&self) -> &str {
        &self.revision
    }
}

fn validate_thresholds(
    raw: BTreeMap<String, f32>,
) -> Result<BTreeMap<EntityType, f32>, CalibrationError> {
    let mut validated = BTreeMap::new();
    for (wire, value) in raw {
        let entity_type = EntityType::from_wire(&wire)
            .ok_or_else(|| CalibrationError::UnknownEntityType { wire: wire.clone() })?;
        if !VALID_THRESHOLD_RANGE.contains(&value) {
            return Err(CalibrationError::ThresholdOutOfRange { wire });
        }
        validated.insert(entity_type, value);
    }
    Ok(validated)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_language_specific_threshold_beats_the_default() {
        let calibration = Calibration::from_json(
            r#"{
            "revision": "t", "default": { "PERSON": 0.50 },
            "languages": { "de": { "PERSON": 0.72 } }
        }"#,
        )
        .expect("parses");
        assert_eq!(calibration.threshold(EntityType::Person, "de"), Some(0.72));
        assert_eq!(calibration.threshold(EntityType::Person, "nl"), Some(0.50));
    }

    #[test]
    fn auto_and_unsupported_languages_fall_back_to_the_default() {
        // There is no pii-detection-lang crate, so "auto" is not resolved to a code.
        // The default block is generated over the pooled six supported
        // languages and this is the only place that fact is enforced.
        let calibration = Calibration::from_json(
            r#"{
            "revision": "t", "default": { "PERSON": 0.50 },
            "languages": { "de": { "PERSON": 0.72 } }
        }"#,
        )
        .expect("parses");
        assert_eq!(
            calibration.threshold(EntityType::Person, "auto"),
            Some(0.50)
        );
        assert_eq!(calibration.threshold(EntityType::Person, "pl"), Some(0.50));
    }

    #[test]
    fn a_type_with_no_entry_anywhere_has_no_threshold_rather_than_a_guessed_one() {
        // Matching the resolver's existing fail-closed rule: an uncalibrated
        // type never matches. Failing open here would give an unreviewed type
        // a MORE permissive bar than every calibrated one.
        let calibration =
            Calibration::from_json(r#"{ "revision": "t", "default": {}, "languages": {} }"#)
                .expect("parses");
        assert_eq!(calibration.threshold(EntityType::StreetAddress, "de"), None);
    }

    #[test]
    fn a_calibration_naming_a_type_the_platform_does_not_have_is_rejected() {
        assert!(
            Calibration::from_json(
                r#"{
            "revision": "t", "default": { "BSN": 0.5 }, "languages": {}
        }"#
            )
            .is_err()
        );
    }

    #[test]
    fn a_threshold_outside_zero_to_one_is_rejected() {
        // A generator bug that emitted a raw logit instead of a probability
        // would otherwise disable a type in production and look like a
        // detection problem.
        assert!(
            Calibration::from_json(
                r#"{
            "revision": "t", "default": { "PERSON": 4.2 }, "languages": {}
        }"#
            )
            .is_err()
        );
    }

    #[test]
    fn a_negative_threshold_is_also_rejected() {
        assert!(
            Calibration::from_json(
                r#"{ "revision": "t", "default": { "PERSON": -0.1 }, "languages": {} }"#
            )
            .is_err()
        );
    }

    #[test]
    fn malformed_json_is_rejected_by_position_only() {
        match Calibration::from_json("{not valid json") {
            Err(CalibrationError::Malformed { .. }) => {}
            other => panic!("expected Malformed, got {other:?}"),
        }
    }

    #[test]
    fn revision_reports_the_loaded_label_verbatim() {
        let calibration = Calibration::from_json(
            r#"{ "revision": "2026-08-22-run3", "default": {}, "languages": {} }"#,
        )
        .expect("parses");
        assert_eq!(calibration.revision(), "2026-08-22-run3");
    }

    #[test]
    fn an_unrecognised_field_is_ignored_rather_than_rejected() {
        // A real calibration.json also carries `generated_by` and `notes` --
        // this parser reads neither, and must not fail the load because of
        // them.
        let calibration = Calibration::from_json(
            r#"{
            "revision": "t", "generated_by": "pii-detection-eval calibrate",
            "default": { "PERSON": 0.5 }, "languages": {},
            "notes": ["it: n=9 is below the sample floor of 20"]
        }"#,
        )
        .expect("extra fields are ignored, not rejected");
        assert_eq!(calibration.threshold(EntityType::Person, "de"), Some(0.5));
    }
}
